<script setup lang="ts">
import { computed, onBeforeUnmount, onMounted, ref, watch } from 'vue'
import { ArrowDownToLine, Check, CheckCheck, ChevronDown, ChevronRight, CircleHelp, Clapperboard, Clock3, Copy, Database, Download, Film, Folder, FolderClosed, FolderOpen, HardDrive, Heart, LayoutGrid, List, LoaderCircle, MoreHorizontal, Plus, RefreshCw, Search, Settings2, ShieldCheck, SlidersHorizontal, Sparkles, Trash2, UsersRound, X } from 'lucide-vue-next'
import VideoPlayer from './components/VideoPlayer.vue'
import { command, demoEnabled, enableDemo, getEnvironment, isDesktop, listenLibrary, mediaUrl, pickFolder, pickMetadata, pickVideos, saveVideo } from './api'
import { fileStem, filterRecordings, formatSize, formatTime, isEditableTarget } from './domain/library'
import type { Environment, FavoriteMode, LibraryView, Recording, Settings, Snapshot, SortOrder } from './types'

const library = ref<Snapshot>({ recordings: [], sources: [], categories: [], settings: { ffmpegPath: '', autoScan: true, continuousPlay: true }, diagnostics: [] })
const environment = ref<Environment | null>(null), view = ref<LibraryView>('all'), account = ref(''), search = ref(''), sort = ref<SortOrder>('newest'), layout = ref<'grid' | 'list'>('grid')
const loading = ref(true), busy = ref(false), operation = ref(''), demoMode = ref(false), selected = ref<string[]>([]), selectMode = ref(false), currentId = ref<string | null>(null)
const autoplayNext = ref(false)
const modal = ref<'sources' | 'import' | 'favorite' | 'category' | 'assign' | 'delete' | 'settings' | 'details' | null>(null)
const actionIds = ref<string[]>([]), favoriteMode = ref<FavoriteMode>('index'), categoryName = ref(''), assignCategories = ref<string[]>([]), deleteTarget = ref<'original' | 'copy' | 'index'>('original')
const sourcePath = ref(''), sourceName = ref(''), sourceKind = ref<'wegame' | 'import'>('wegame'), discovered = ref<string[]>([]), importPaths = ref<string[]>([]), metadataPath = ref<string | null>(null)
const settingsDraft = ref<Settings>({ ffmpegPath: '', autoScan: true, continuousPlay: true }), detailRecording = ref<Recording | null>(null)
const toast = ref<{ message: string; type: 'success' | 'error' } | null>(null), searchInput = ref<HTMLInputElement | null>(null), thumbnailUrls = ref<Record<string, string>>({})
let toastTimer: ReturnType<typeof setTimeout> | undefined, stopListening = () => {}, thumbnailGeneration = 0
const accounts = computed(() => [...new Set(library.value.recordings.map(r => r.account).filter(Boolean))].sort())
const imports = computed(() => [...new Set([...library.value.sources.filter(s => s.kind === 'import').map(s => s.id), ...library.value.recordings.filter(r => r.sourceId.startsWith('files:')).map(r => r.sourceId)])])
const recordings = computed(() => filterRecordings(library.value.recordings, view.value, account.value, search.value, sort.value, imports.value))
const totalFavorites = computed(() => library.value.recordings.filter(r => r.favoriteMode !== 'none').length)
const totalKills = computed(() => library.value.recordings.reduce((sum, r) => sum + r.events.filter(e => e.kind === 'kill').length, 0))
const currentRecording = computed(() => library.value.recordings.find(r => r.id === currentId.value) || null)
const currentIndex = computed(() => recordings.value.findIndex(r => r.id === currentId.value))
const nextAvailable = computed(() => currentIndex.value >= 0 && currentIndex.value < recordings.value.length - 1)
const allSelected = computed(() => recordings.value.length > 0 && recordings.value.every(r => selected.value.includes(r.id)))
const actionRecordings = computed(() => library.value.recordings.filter(r => actionIds.value.includes(r.id)))
const title = computed(() => view.value === 'favorites' ? '我的收藏' : view.value === 'imports' ? '外部导入' : view.value.startsWith('category:') ? library.value.categories.find(c => c.id === view.value.slice(9))?.name || '自定义分类' : view.value.startsWith('source:') ? library.value.sources.find(s => s.id === view.value.slice(7))?.name || '录像来源' : '全部录像')
const storage = computed(() => formatSize(library.value.recordings.reduce((sum, r) => sum + r.size, 0)))
const isFiltered = computed(() => !!account.value || !!search.value)

function notify(message: string, type: 'success' | 'error' = 'success') { toast.value = { message, type }; clearTimeout(toastTimer); toastTimer = setTimeout(() => toast.value = null, type === 'error' ? 6500 : 4500) }
function errorText(error: unknown): string { return typeof error === 'string' ? error : error instanceof Error ? error.message : String(error) }
async function run<T>(task: () => Promise<T>, success?: string): Promise<T | undefined> {
  if (busy.value) return
  busy.value = true
  try { const result = await task(); if (success) notify(success); return result } catch (error) { notify(errorText(error), 'error'); return undefined } finally { busy.value = false; operation.value = '' }
}
function apply(snapshot: Snapshot) { library.value = snapshot; selected.value = selected.value.filter(id => snapshot.recordings.some(r => r.id === id)); if (currentId.value && !snapshot.recordings.some(r => r.id === currentId.value)) currentId.value = null }
async function refresh() { try { apply(await command<Snapshot>('get_library')) } catch (error) { notify(errorText(error), 'error') } }
async function mutate(name: string, args: Record<string, unknown>, message: string, close = true) { if (busy.value) return; const snapshot = await run(() => command<Snapshot>(name, args), message); if (snapshot) { apply(snapshot); if (close) modal.value = null } else await refresh(); return snapshot }
function changeView(value: LibraryView) { view.value = value; selected.value = []; currentId.value = null }
async function prepareRecording(recording: Recording, autoplay = false) {
  if (busy.value) return
  if (isDesktop) {
    operation.value = '正在读取视频参数…'
    const probed = await run(() => command<Recording>('get_recording_media', { id: recording.id }))
    if (probed) library.value.recordings = library.value.recordings.map(row => row.id === probed.id ? probed : row)
    else await refresh()
  }
  autoplayNext.value = autoplay; currentId.value = recording.id
}
async function openRecording(recording: Recording) { if (selectMode.value) { toggleSelected(recording.id); return } await prepareRecording(recording) }
function toggleSelected(id: string) { selected.value = selected.value.includes(id) ? selected.value.filter(item => item !== id) : [...selected.value, id] }
function toggleAll() { selected.value = allSelected.value ? [] : recordings.value.map(r => r.id) }
function toggleSelectMode() { selectMode.value = !selectMode.value; if (!selectMode.value) selected.value = [] }
async function nextRecording() { if (nextAvailable.value) await prepareRecording(recordings.value[currentIndex.value + 1], true) }
function openFavorite(ids: string[]) { actionIds.value = ids; favoriteMode.value = library.value.recordings.find(r => r.id === ids[0])?.favoriteMode === 'copy' ? 'copy' : 'index'; modal.value = 'favorite' }
function openAssign(ids: string[]) { actionIds.value = ids; assignCategories.value = [...(library.value.recordings.find(r => r.id === ids[0])?.categoryIds || [])]; modal.value = 'assign' }
function openDelete(ids: string[]) { actionIds.value = ids; deleteTarget.value = 'original'; modal.value = 'delete' }
function openSettings() { settingsDraft.value = { ...library.value.settings }; modal.value = 'settings' }
function showDetails(recording: Recording) { detailRecording.value = recording; modal.value = 'details' }
async function scan() { operation.value = '正在扫描录像来源…'; await mutate('scan_sources', {}, '录像库已更新', false) }
async function chooseSource() { const path = await run(() => pickFolder('选择 ACLOS / 录像根目录')); if (path) { sourcePath.value = path; sourceName.value = path.split(/[\\/]/).filter(Boolean).pop() || '录像来源' } }
async function discover() { const paths = await run(() => command<string[]>('discover_sources')); if (paths) { discovered.value = paths; if (!paths.length) notify('未发现 ACLOS 目录，请手动选择实际录像目录。') } }
async function addSource() { if (!sourcePath.value.trim()) return; const result = await mutate('add_source', { path: sourcePath.value.trim(), name: sourceName.value.trim() || '录像来源', kind: sourceKind.value }, '已添加来源并扫描录像', false); if (result) { sourcePath.value = ''; sourceName.value = '' } }
async function chooseVideos() { const paths = await run(pickVideos); if (paths?.length) importPaths.value = [...new Set([...importPaths.value, ...paths])] }
async function chooseMetadata() { const path = await run(pickMetadata); if (path) metadataPath.value = path }
async function importFiles() { if (!importPaths.value.length) return; const result = await mutate('import_files', { paths: importPaths.value, metadataPath: metadataPath.value }, '录像已导入'); if (result) { importPaths.value = []; metadataPath.value = null; view.value = 'imports' } }
async function saveSettings() { const result = await mutate('update_settings', { settings: settingsDraft.value }, '设置已保存'); if (result) environment.value = await getEnvironment() }
async function toggleContinuous() { await mutate('update_settings', { settings: { ...library.value.settings, continuousPlay: !library.value.settings.continuousPlay } }, '播放设置已更新', false) }
async function exportClip(start: number, end: number, precise: boolean) {
  const recording = currentRecording.value; if (!recording) return
  const path = await run(() => saveVideo(`${fileStem(recording.title)}_${Math.floor(start)}-${Math.floor(end)}.mp4`)); if (!path) return
  operation.value = '正在导出 MP4 片段…'; await run(() => command<string>('export_clip', { id: recording.id, start, end, outputPath: path, precise }), '片段已导出到所选位置')
}
async function exportEvents(before: number, after: number) {
  const recording = currentRecording.value; if (!recording) return
  const outputDir = await run(() => pickFolder('选择击杀片段导出文件夹')); if (!outputDir) return
  operation.value = '正在导出击杀片段…'; const results = await run(() => command<string[]>('export_events', { id: recording.id, before, after, outputDir })); if (results) notify(`已导出 ${results.length} 个击杀片段`)
}
function startDemo() { apply(enableDemo()); demoMode.value = true; notify('演示模式已开启。样例视频与事件不来自本机。') }
function exitDemo() { window.location.reload() }
function dateLabel(value: number) { return new Date(value * 1000).toLocaleString('zh-CN', { month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit', timeZone: demoMode.value ? 'Asia/Shanghai' : undefined }) }
function poster(recording: Recording) { return recording.thumbnailPath ? mediaUrl(recording.thumbnailPath) : thumbnailUrls.value[recording.id] || '' }
function categoryCount(id: string) { return library.value.recordings.filter(r => r.categoryIds.includes(id)).length }
function sourceCount(id: string) { return library.value.recordings.filter(r => r.sourceId === id).length }
function hotkeys(event: KeyboardEvent) { if (modal.value) { if (event.key === 'Escape' && !busy.value) modal.value = null; return } if ((event.ctrlKey || event.metaKey) && event.key.toLowerCase() === 'k') { event.preventDefault(); searchInput.value?.focus() } if (!currentId.value && !isEditableTarget(event.target) && event.key === 'Escape') { selected.value = []; selectMode.value = false } }
watch(recordings, async () => {
  if (!isDesktop || !environment.value?.ffmpegAvailable) return
  const generation = ++thumbnailGeneration, pending = recordings.value.filter(r => r.available && !r.thumbnailPath && !thumbnailUrls.value[r.id]).slice(0, 12)
  for (const recording of pending) { if (generation !== thumbnailGeneration) return; try { const path = await command<string>('get_thumbnail', { id: recording.id, time: Math.min(2, recording.duration / 3) }); thumbnailUrls.value[recording.id] = mediaUrl(path) } catch { /* Metadata-only recordings still have a useful placeholder. */ } }
})
onMounted(async () => { window.addEventListener('keydown', hotkeys); try { environment.value = await getEnvironment(); await refresh(); stopListening = await listenLibrary(() => { void refresh() }, message => { operation.value = message.startsWith('正在') ? message : ''; if (message.includes('失败')) notify(message, 'error') }) } catch (error) { notify(errorText(error), 'error') } finally { loading.value = false } })
onBeforeUnmount(() => { stopListening(); window.removeEventListener('keydown', hotkeys); clearTimeout(toastTimer); thumbnailGeneration++ })
</script>

<template>
  <div class="app-shell">
    <aside class="sidebar">
      <div class="brand"><div class="brand-symbol"><Clapperboard :size="23" /></div><div><strong>MOMENTS<span>+</span></strong><small>无畏时刻增强播放器</small></div></div>
      <div class="workspace-label">个人录像库 <span>LOCAL</span></div>
      <nav class="main-nav" aria-label="录像库导航">
        <button :class="{ active: view === 'all' }" @click="changeView('all')"><LayoutGrid :size="19" /><span>全部录像</span><small>{{ library.recordings.length }}</small></button>
        <button :class="{ active: view === 'favorites' }" @click="changeView('favorites')"><Heart :size="19" /><span>我的收藏</span><small>{{ totalFavorites }}</small></button>
        <button :class="{ active: view === 'imports' }" @click="changeView('imports')"><ArrowDownToLine :size="19" /><span>外部导入</span><small>{{ library.recordings.filter(r => imports.includes(r.sourceId)).length }}</small></button>
      </nav>
      <div class="nav-section-title">自定义分类<button class="icon-button" title="创建分类" aria-label="创建分类" @click="categoryName = ''; modal = 'category'"><Plus :size="16" /></button></div>
      <nav class="category-nav" aria-label="自定义分类"><button v-for="category in library.categories" :key="category.id" :class="{ active: view === `category:${category.id}` }" @click="changeView(`category:${category.id}`)"><FolderClosed :size="17" /><span>{{ category.name }}</span><small>{{ categoryCount(category.id) }}</small></button><p v-if="!library.categories.length" class="sidebar-empty">为你的精彩瞬间分个类</p></nav>
      <div class="nav-section-title source-title">录像来源<button class="icon-button" title="管理来源" aria-label="管理来源" @click="modal = 'sources'"><Plus :size="16" /></button></div>
      <nav class="source-nav" aria-label="录像来源"><button v-for="source in library.sources" :key="source.id" :class="{ active: view === `source:${source.id}` }" @click="changeView(`source:${source.id}`)"><span class="source-dot" :class="{ imported: source.kind === 'import' }" /><div><span>{{ source.name }}</span><small>{{ source.account || (source.kind === 'import' ? '外部电脑录像' : '自动识别账号') }}</small></div><ChevronRight :size="13" /></button><button v-if="!library.sources.length" class="add-source-link" @click="modal = 'sources'"><Plus :size="16" /> 连接录像目录</button></nav>
      <div class="sidebar-bottom"><div class="local-storage"><HardDrive :size="16" /><span>本地录像</span><strong>{{ storage }}</strong></div><button class="settings-nav" @click="openSettings"><Settings2 :size="18" /><span>设置与工具</span><span class="version">v0.1.0</span></button><div class="privacy-footnote"><ShieldCheck :size="13" /> 本地管理 · 官方数据只读</div></div>
    </aside>
    <main class="main-content">
      <header class="topbar"><div class="breadcrumb"><span>我的空间</span><ChevronRight :size="13" /><strong>{{ currentRecording ? '播放器' : title }}</strong></div><div class="topbar-status"><span class="status-dot" :class="{ inactive: !isDesktop }" /><span>{{ demoMode ? '浏览器演示' : !isDesktop ? '浏览器预览' : library.settings.autoScan ? '自动监测已开启' : '手动更新' }}</span><span class="topbar-divider" /><button class="icon-button" aria-label="设置" @click="openSettings"><Settings2 :size="17" /></button></div></header>
      <VideoPlayer v-if="currentRecording" :key="currentRecording.id" :recording="currentRecording" :environment="environment" :continuous-play="library.settings.continuousPlay" :next-available="nextAvailable" :busy="busy" :autoplay="autoplayNext" :shortcuts-enabled="modal === null" @close="currentId = null" @favorite="openFavorite([currentRecording.id])" @next="nextRecording" @toggle-continuous="toggleContinuous" @export-clip="exportClip" @export-events="exportEvents" />
      <div v-else class="library-page">
        <div v-if="demoMode" class="demo-banner"><CircleHelp :size="16" /><span>演示模式：展示样例录像与模拟事件。原始文件操作、永久副本、导出需在桌面端运行。</span><button class="text-button" @click="exitDemo">退出演示</button></div>
        <section class="page-heading"><div><div class="eyebrow">YOUR HIGHLIGHTS, REPLAYED.</div><h1>{{ title }}<span class="count-badge">{{ recordings.length }}</span></h1><p>每一个精彩瞬间，都在这里。<span v-if="view === 'all' && library.recordings.length"> 已识别 {{ accounts.length }} 个账号 · {{ totalKills }} 次击杀事件</span></p></div><div class="heading-actions"><button class="secondary-button" :disabled="busy || !isDesktop" @click="scan"><RefreshCw :size="16" :class="{ spinning: busy }" /> 刷新</button><button class="primary-button" :disabled="busy" @click="modal = 'import'"><Plus :size="17" /> 导入录像</button></div></section>
        <div class="library-toolbar"><div class="search-field"><Search :size="17" /><input ref="searchInput" v-model="search" placeholder="搜索录像、账号或事件…" aria-label="搜索录像" /><button v-if="search" class="icon-button" aria-label="清空搜索" @click="search = ''"><X :size="14" /></button><kbd v-else>Ctrl K</kbd></div><div class="account-select"><UsersRound :size="16" /><select v-model="account" aria-label="按账号筛选"><option value="">全部账号</option><option v-for="item in accounts" :key="item" :value="item">{{ item }}</option></select><ChevronDown :size="13" /></div><select v-model="sort" class="sort-select" aria-label="排序"><option value="newest">最新优先</option><option value="oldest">最早优先</option><option value="duration">时长优先</option><option value="title">名称排序</option></select><div class="view-switch"><button :class="{ active: layout === 'grid' }" aria-label="网格视图" :aria-pressed="layout === 'grid'" @click="layout = 'grid'"><LayoutGrid :size="17" /></button><button :class="{ active: layout === 'list' }" aria-label="列表视图" :aria-pressed="layout === 'list'" @click="layout = 'list'"><List :size="18" /></button></div></div>
        <div class="library-subbar"><div><span>{{ isFiltered ? '筛选结果' : view === 'favorites' ? '珍藏的精彩瞬间' : '全部精彩瞬间' }}</span><small v-if="isFiltered">{{ recordings.length }} 个录像</small><button v-if="isFiltered" class="text-button" @click="account = ''; search = ''">重置筛选</button></div><div><button v-if="view.startsWith('category:')" class="text-button muted" :disabled="busy" @click="mutate('delete_category', { id: view.slice(9) }, '分类已移除').then(result => { if (result) changeView('all') })"><Trash2 :size="14" /> 删除分类</button><button v-if="selectMode" class="text-button" @click="toggleAll"><CheckCheck :size="15" /> {{ allSelected ? '取消全选' : '全选' }}</button><button class="text-button" :class="{ 'accent-text': selectMode }" @click="toggleSelectMode"><CheckCheck :size="15" /> {{ selectMode ? '完成选择' : '批量管理' }}</button></div></div>
        <div v-if="loading" class="loading-state"><LoaderCircle :size="28" class="spinning" /><p>正在打开你的录像库…</p></div>
        <div v-else-if="!recordings.length" class="empty-state"><div class="empty-illustration"><div class="empty-backplate" /><Film :size="42" /><span><Plus :size="15" /></span></div><h2>{{ isFiltered ? '没有找到匹配的录像' : view === 'favorites' ? '收藏你想留住的高光' : view.startsWith('category:') ? '这个分类还没有录像' : '让精彩瞬间回到眼前' }}</h2><p>{{ isFiltered ? '试试其他关键词，或查看全部账号的录像。' : view === 'favorites' ? '选择索引收藏快速整理，或保存永久副本留住视频。' : view.startsWith('category:') ? '在录像卡片或批量管理中，将录像加入此分类。' : '连接本机 WeGame / ACLOS 录像目录，或导入其他电脑的视频。' }}</p><div class="empty-actions"><button v-if="isFiltered" class="primary-button" @click="search = ''; account = ''">清空筛选</button><template v-else><button class="primary-button" @click="modal = 'sources'"><FolderOpen :size="17" /> 连接录像目录</button><button class="secondary-button" @click="modal = 'import'"><Download :size="16" /> 导入视频</button></template></div><button v-if="!isDesktop && !demoMode" class="demo-start text-button" @click="startDemo"><Sparkles :size="15" /> 体验界面演示 <ChevronRight :size="14" /></button><div v-if="!isDesktop" class="empty-desktop-note">本机扫描、回收站和导出功能需要启动 Tauri 桌面应用</div></div>
        <div v-else-if="layout === 'grid'" class="recording-grid"><article v-for="(recording, index) in recordings" :key="recording.id" class="recording-card" :class="{ selected: selected.includes(recording.id), unavailable: !recording.available && !recording.favoritePath }"><div class="card-preview" :class="[`scene-${index % 6}`, { demo: demoMode }]" @click="openRecording(recording)"><img v-if="poster(recording)" :src="poster(recording)" :alt="`${recording.title} 缩略图`" loading="lazy" /><template v-else><div class="scene-lines"><i /><i /><i /></div><Clapperboard class="placeholder-film" :size="34" /><span class="thumbnail-label">{{ demoMode ? '演示样例' : '录像预览' }}</span></template><span v-if="!recording.available && !recording.favoritePath" class="unavailable-label">文件不可用</span><span class="duration-chip">{{ formatTime(recording.duration) }}</span><span v-if="recording.favoritePath" class="copy-chip"><Copy :size="11" /> 永久副本</span><button class="card-selection" :class="{ visible: selectMode || selected.includes(recording.id), checked: selected.includes(recording.id) }" :aria-label="`选择 ${recording.title}`" :aria-pressed="selected.includes(recording.id)" @click.stop="toggleSelected(recording.id); selectMode = true"><Check v-if="selected.includes(recording.id)" :size="14" /></button><button class="card-play" :aria-label="`播放 ${recording.title}`" @click.stop="openRecording(recording)"><ChevronRight :size="27" fill="currentColor" /></button></div><div class="card-body"><div class="card-title"><button @click="openRecording(recording)" :title="recording.title">{{ recording.title }}</button><button class="icon-button favorite-icon" :class="{ 'is-favorite': recording.favoriteMode !== 'none' }" :aria-label="`收藏 ${recording.title}`" @click="openFavorite([recording.id])"><Heart :size="17" :fill="recording.favoriteMode !== 'none' ? 'currentColor' : 'none'" /></button></div><div class="card-meta"><span class="account-avatar">{{ (recording.account || '?').slice(0, 1).toUpperCase() }}</span><span class="card-account">{{ recording.account || '未知账号' }}</span><span class="card-resolution">{{ recording.height ? `${recording.height}p` : '视频' }}</span></div><div class="card-footer"><time>{{ dateLabel(recording.createdAt) }}</time><span v-if="recording.events.length" class="event-count"><span class="event-dot" /> {{ recording.events.filter(e => e.kind === 'kill').length }} 击杀</span><span v-else class="no-event">无事件元数据</span><button class="icon-button" aria-label="录像信息与管理" @click="showDetails(recording)"><MoreHorizontal :size="17" /></button></div></div></article></div>
        <div v-else class="recording-table"><div class="table-header"><span>录像</span><span>账号</span><span>日期</span><span>时长 / 大小</span><span>操作</span></div><div v-for="recording in recordings" :key="recording.id" class="table-row" :class="{ selected: selected.includes(recording.id) }"><div class="table-recording"><button v-if="selectMode" class="row-check" :class="{ checked: selected.includes(recording.id) }" :aria-label="`选择 ${recording.title}`" @click="toggleSelected(recording.id)"><Check v-if="selected.includes(recording.id)" :size="13" /></button><button class="table-preview" @click="openRecording(recording)"><img v-if="poster(recording)" :src="poster(recording)" alt="" /><Film v-else :size="19" /></button><button class="table-title" @click="openRecording(recording)">{{ recording.title }}<small>{{ recording.events.length ? `${recording.events.length} 个事件` : '无事件元数据' }}{{ recording.favoritePath ? ' · 永久副本' : '' }}</small></button></div><span class="table-account">{{ recording.account || '未知账号' }}</span><time>{{ dateLabel(recording.createdAt) }}</time><span class="table-duration">{{ formatTime(recording.duration) }}<small>{{ formatSize(recording.size) }}</small></span><div class="table-actions"><button class="icon-button" :class="{ 'is-favorite': recording.favoriteMode !== 'none' }" aria-label="收藏" @click="openFavorite([recording.id])"><Heart :size="17" :fill="recording.favoriteMode !== 'none' ? 'currentColor' : 'none'" /></button><button class="icon-button" aria-label="录像信息" @click="showDetails(recording)"><MoreHorizontal :size="18" /></button></div></div></div>
        <footer v-if="recordings.length" class="library-footer"><span>共 {{ recordings.length }} 个录像</span><span><Database :size="12" /> {{ demoMode ? '样例数据 · 仅用于演示' : '本地 SQLite 索引' }}</span></footer>
        <div v-if="selected.length" class="batch-bar"><div><span class="batch-count">{{ selected.length }}</span> 个录像已选择<button class="text-button" @click="selected = []">清空</button></div><div><button @click="openFavorite(selected)"><Heart :size="16" /> 收藏</button><button @click="openAssign(selected)"><Folder :size="16" /> 分类</button><span /><button class="danger-text" @click="openDelete(selected)"><Trash2 :size="16" /> 删除</button></div></div>
      </div>
      <div v-if="busy || operation" class="operation-status"><LoaderCircle :size="14" class="spinning" /> {{ operation || '正在处理…' }}</div>
    </main>
    <Transition name="toast"><div v-if="toast" class="toast-message" :class="toast.type" role="status"><Check v-if="toast.type === 'success'" :size="17" /><CircleHelp v-else :size="18" /><span>{{ toast.message }}</span><button class="icon-button" aria-label="关闭通知" @click="toast = null"><X :size="14" /></button></div></Transition>
    <div v-if="modal" class="modal-backdrop" @mousedown.self="!busy && (modal = null)"><section class="modal" :class="{ 'modal-wide': modal === 'sources' || modal === 'settings' }" role="dialog" aria-modal="true" :aria-label="{ sources: '管理录像来源', import: '导入外部录像', favorite: '收藏方式', category: '创建分类', assign: '设置分类', delete: '删除录像', settings: '设置与工具', details: '录像详情' }[modal]"><header class="modal-header"><h2>{{ { sources: '管理录像来源', import: '导入外部录像', favorite: '收藏精彩瞬间', category: '创建自定义分类', assign: '设置录像分类', delete: '删除录像', settings: '设置与工具', details: '录像详情' }[modal] }}</h2><button class="icon-button" :disabled="busy" aria-label="关闭对话框" @click="modal = null"><X :size="19" /></button></header>
      <template v-if="modal === 'sources'"><p class="modal-description">连接本机多个账号的录像目录。ACLOS 官方元数据始终只读。</p><div class="source-list"><div v-for="source in library.sources" :key="source.id" class="source-item"><FolderOpen :size="21" /><div><strong>{{ source.name }}</strong><span>{{ source.path }}</span><small>{{ source.status }} · {{ sourceCount(source.id) }} 个录像</small></div><button class="icon-button" :disabled="busy" title="移除来源" aria-label="移除来源" @click="mutate('remove_source', { id: source.id }, '来源已移除', false)"><Trash2 :size="16" /></button></div><p v-if="!library.sources.length" class="small-empty">尚未连接任何目录</p></div><div class="modal-divider" /><div class="form-heading"><h3>添加录像目录</h3><button class="text-button" :disabled="busy || !isDesktop" @click="discover"><Search :size="14" /> 自动查找</button></div><div v-if="discovered.length" class="discovered-sources"><button v-for="path in discovered" :key="path" @click="sourcePath = path; sourceName = path.split(/[\\/]/).filter(Boolean).pop() || 'ACLOS'"><Folder :size="14" /><span>{{ path }}</span><Plus :size="14" /></button></div><label class="form-label">目录路径<div class="input-with-button"><input v-model="sourcePath" placeholder="选择 ACLOS 或包含录像的目录" /><button class="secondary-button" :disabled="busy" @click="chooseSource">浏览</button></div></label><div class="form-columns"><label class="form-label">来源名称<input v-model="sourceName" placeholder="例如：WeGame 主账号" /></label><label class="form-label">来源类型<select v-model="sourceKind"><option value="wegame">WeGame / ACLOS</option><option value="import">外部录像目录</option></select></label></div><footer class="modal-footer"><button class="secondary-button" @click="modal = null">完成</button><button class="primary-button" :disabled="busy || !sourcePath.trim()" @click="addSource"><Plus :size="16" /> 添加并扫描</button></footer></template>
      <template v-else-if="modal === 'import'"><p class="modal-description">导入其他电脑的视频，按需关联 ACLOS 元数据。视频保留在你选择的位置。</p><button class="import-dropzone" :disabled="busy" @click="chooseVideos"><ArrowDownToLine :size="29" /><strong>{{ importPaths.length ? `已选择 ${importPaths.length} 个视频` : '选择视频文件' }}</strong><span>支持 MP4、MKV、MOV、WebM、AVI</span></button><div v-if="importPaths.length" class="import-file-list"><div v-for="path in importPaths" :key="path"><Film :size="14" /><span :title="path">{{ path.split(/[\\/]/).pop() }}</span><button class="icon-button" aria-label="移除此文件" @click="importPaths = importPaths.filter(p => p !== path)"><X :size="13" /></button></div></div><div class="metadata-picker"><div><Database :size="18" /><span>ACLOS 元数据<small>{{ metadataPath ? metadataPath.split(/[\\/]/).pop() : '可选 · JSON / 无扩展名账号缓存' }}</small></span></div><button class="secondary-button" :disabled="busy" @click="chooseMetadata">{{ metadataPath ? '重新选择' : '选择文件' }}</button><button v-if="metadataPath" class="icon-button" aria-label="移除元数据文件" @click="metadataPath = null"><X :size="14" /></button></div><p class="inline-hint">未验证的元数据格式会保留诊断信息，不会推测击杀事件。</p><footer class="modal-footer"><button class="secondary-button" @click="modal = null">取消</button><button class="primary-button" :disabled="busy || !importPaths.length" @click="importFiles">导入 {{ importPaths.length || '' }} 个录像</button></footer></template>
      <template v-else-if="modal === 'favorite'"><p class="modal-description">为 {{ actionIds.length }} 个录像选择保存方式。</p><label class="choice-card" :class="{ selected: favoriteMode === 'index' }"><input v-model="favoriteMode" type="radio" value="index" /><Heart :size="20" /><div><strong>索引收藏<span>轻量</span></strong><p>记录收藏状态，不复制视频。没有永久副本时，删除原始文件将无法播放。</p></div></label><label class="choice-card" :class="{ selected: favoriteMode === 'copy' }"><input v-model="favoriteMode" type="radio" value="copy" /><Copy :size="20" /><div><strong>永久副本<span>长期保存</span></strong><p>复制到应用收藏目录。删除原始录像后，副本仍可播放。</p></div></label><label class="choice-card compact-choice" :class="{ selected: favoriteMode === 'none' }"><input v-model="favoriteMode" type="radio" value="none" /><div><strong>取消收藏</strong><p>仅取消收藏状态，已创建副本请在删除管理中单独移除。</p></div></label><footer class="modal-footer"><button class="secondary-button" @click="modal = null">取消</button><button class="primary-button" :disabled="busy" @click="mutate('set_favorites', { ids: actionIds, mode: favoriteMode }, '收藏状态已更新')">保存</button></footer></template>
      <template v-else-if="modal === 'category'"><p class="modal-description">用分类整理高光、复盘或不同玩法的录像。</p><label class="form-label">分类名称<input v-model="categoryName" maxlength="40" placeholder="例如：高光时刻" autofocus @keydown.enter="categoryName.trim() && mutate('create_category', { name: categoryName.trim() }, '分类已创建')" /></label><footer class="modal-footer"><button class="secondary-button" @click="modal = null">取消</button><button class="primary-button" :disabled="busy || !categoryName.trim()" @click="mutate('create_category', { name: categoryName.trim() }, '分类已创建')">创建分类</button></footer></template>
      <template v-else-if="modal === 'assign'"><p class="modal-description">选中的 {{ actionIds.length }} 个录像将使用以下分类，可同时属于多个分类。</p><div class="category-checklist"><label v-for="category in library.categories" :key="category.id"><input v-model="assignCategories" type="checkbox" :value="category.id" /><Folder :size="17" /><span>{{ category.name }}</span></label><p v-if="!library.categories.length" class="small-empty">先在左侧创建一个分类</p></div><footer class="modal-footer"><button class="secondary-button" @click="modal = null">取消</button><button class="primary-button" :disabled="busy" @click="mutate('set_categories', { ids: actionIds, categoryIds: assignCategories }, '录像分类已更新')">保存分类</button></footer></template>
      <template v-else-if="modal === 'delete'"><p class="modal-description">管理 {{ actionIds.length }} 个录像。磁盘文件会送入 Windows 回收站。</p><label class="choice-card" :class="{ selected: deleteTarget === 'original' }"><input v-model="deleteTarget" type="radio" value="original" /><Trash2 :size="20" /><div><strong>删除原始录像</strong><p>移除源目录中的视频。永久收藏副本会保留。</p></div></label><label class="choice-card" :class="{ selected: deleteTarget === 'copy' }"><input v-model="deleteTarget" type="radio" value="copy" /><Copy :size="20" /><div><strong>删除收藏副本</strong><p>仅移除应用保存的副本，保留原始视频。</p></div></label><label class="choice-card" :class="{ selected: deleteTarget === 'index' }"><input v-model="deleteTarget" type="radio" value="index" /><Database :size="20" /><div><strong>仅移除库内索引</strong><p>保留视频文件，后续扫描不会重新加入。可通过手动导入恢复。</p></div></label><div class="delete-preview"><strong>操作对象</strong><span v-for="recording in actionRecordings.slice(0, 3)" :key="recording.id">{{ recording.title }}</span><small v-if="actionRecordings.length > 3">以及另外 {{ actionRecordings.length - 3 }} 个录像</small></div><footer class="modal-footer"><button class="secondary-button" @click="modal = null">取消</button><button class="danger-button" :disabled="busy" @click="mutate('delete_recordings', { ids: actionIds, target: deleteTarget }, deleteTarget === 'index' ? '库内索引已移除' : '所选文件已送入回收站')"><Trash2 :size="16" /> {{ deleteTarget === 'index' ? '移除索引' : '移至回收站' }}</button></footer></template>
      <template v-else-if="modal === 'settings'"><p class="modal-description">播放与工具配置保存在本机，不会访问游戏进程。</p><div class="settings-option"><div><strong>自动监测录像目录</strong><p>目录内容变化后，增量更新本地录像库。</p></div><input v-model="settingsDraft.autoScan" type="checkbox" class="switch-checkbox" aria-label="自动监测录像目录" /></div><div class="settings-option"><div><strong>连续播放</strong><p>播放结束后自动打开当前列表的下一个录像。</p></div><input v-model="settingsDraft.continuousPlay" type="checkbox" class="switch-checkbox" aria-label="连续播放" /></div><div class="modal-divider" /><label class="form-label">FFmpeg 可执行文件路径<input v-model="settingsDraft.ffmpegPath" placeholder="留空使用系统 PATH 中的 ffmpeg" /></label><div class="tool-status" :class="{ ready: environment?.ffmpegAvailable }"><span class="status-dot" :class="{ inactive: !environment?.ffmpegAvailable }" />{{ environment?.ffmpegAvailable ? 'FFmpeg 可用 · 支持导出与缩略图' : '尚未检测到 FFmpeg · 可播放原始视频' }}</div><p v-if="environment?.ffmpegPath" class="settings-path">{{ environment.ffmpegPath }}</p><div class="modal-divider" /><div class="diagnostics"><h3><ShieldCheck :size="16" /> 数据与诊断</h3><p>应用索引目录：{{ environment?.dataDir || '加载中…' }}</p><ul v-if="library.diagnostics.length"><li v-for="(diagnostic, index) in library.diagnostics.slice(0, 12)" :key="index">{{ diagnostic }}</li></ul><p v-else>暂无诊断。支持的元数据将由独立适配器读取。</p></div><footer class="modal-footer"><button class="secondary-button" @click="modal = null">取消</button><button class="primary-button" :disabled="busy" @click="saveSettings">保存设置</button></footer></template>
      <template v-else-if="modal === 'details' && detailRecording"><dl class="detail-list"><div><dt>录像名称</dt><dd>{{ detailRecording.title }}</dd></div><div><dt>来源账号</dt><dd>{{ detailRecording.account || '未知账号' }}</dd></div><div><dt>视频参数</dt><dd>{{ detailRecording.width }} × {{ detailRecording.height }} · {{ detailRecording.fps }} FPS · {{ formatSize(detailRecording.size) }}</dd></div><div><dt>元数据状态</dt><dd>{{ detailRecording.metadataStatus }}</dd></div><div><dt>原始文件</dt><dd>{{ detailRecording.path }}</dd></div><div v-if="detailRecording.favoritePath"><dt>收藏副本</dt><dd>{{ detailRecording.favoritePath }}</dd></div></dl><div class="detail-actions"><button class="secondary-button" @click="openFavorite([detailRecording.id])"><Heart :size="16" /> 收藏管理</button><button class="secondary-button" @click="openAssign([detailRecording.id])"><Folder :size="16" /> 设置分类</button><button class="secondary-button danger-text" @click="openDelete([detailRecording.id])"><Trash2 :size="16" /> 删除管理</button></div><footer class="modal-footer"><button class="primary-button" @click="openRecording(detailRecording); modal = null">打开录像</button></footer></template>
    </section></div>
  </div>
</template>
